/**
 * Theme-switch animation for the portal's dark/light toggle.
 *
 * Three modes, decided once per click by `pickThemeTransitionMode`:
 *
 *   "reveal"  — View Transitions API. The browser snapshots the old theme, we
 *               flip `data-theme` inside the update callback, and the live new
 *               theme is revealed through a circle that grows out of the
 *               toggle button (`clip-path` on `::view-transition-new(root)`).
 *   "fade"    — no View Transitions (older Firefox / Safari). A short colour
 *               cross-fade: `html.nx-theme-fading` (app/globals.css) gives
 *               every element a ~240 ms transition on colour properties only,
 *               for the duration of the switch, and is removed afterwards.
 *   "instant" — `prefers-reduced-motion: reduce`. Plain attribute flip.
 *
 * The pure helpers (mode decision + reveal geometry) carry no DOM access so
 * test/theme-transition.test.ts can exercise them directly.
 */

export type ThemeTransitionMode = "reveal" | "fade" | "instant";

export function pickThemeTransitionMode(opts: {
  reducedMotion: boolean;
  supportsViewTransitions: boolean;
  /** `document.visibilityState === "hidden"` — VT aborts on hidden documents. */
  hidden?: boolean;
}): ThemeTransitionMode {
  if (opts.reducedMotion || opts.hidden) return "instant";
  return opts.supportsViewTransitions ? "reveal" : "fade";
}

export interface RevealGeometry {
  /** Circle centre, CSS px from the viewport's top-left. */
  x: number;
  y: number;
  /** Radius that reaches the farthest viewport corner from (x, y). */
  radius: number;
}

/**
 * Centre of the toggle button, clamped into the viewport, plus the radius
 * needed to cover the whole screen from there. With no origin (keyboard
 * activation through a detached node, or a zero-size rect) it falls back to
 * the top-right corner, which is where the toggle lives in the top bar.
 */
export function revealGeometry(
  rect: { left: number; top: number; width: number; height: number } | null | undefined,
  viewport: { width: number; height: number },
): RevealGeometry {
  const w = Math.max(0, viewport.width);
  const h = Math.max(0, viewport.height);
  let x = w;
  let y = 0;
  if (rect && Number.isFinite(rect.left) && Number.isFinite(rect.top) && (rect.width > 0 || rect.height > 0)) {
    x = rect.left + rect.width / 2;
    y = rect.top + rect.height / 2;
  }
  x = Math.min(Math.max(x, 0), w);
  y = Math.min(Math.max(y, 0), h);
  const radius = Math.ceil(Math.hypot(Math.max(x, w - x), Math.max(y, h - y)));
  return { x, y, radius };
}

export const REVEAL_DURATION_MS = 520;
export const FADE_DURATION_MS = 240;
/** easeInOutCubic-ish: a soft start so the circle doesn't "pop", a long settle. */
export const REVEAL_EASING = "cubic-bezier(0.65, 0, 0.35, 1)";

/* ── DOM runner ─────────────────────────────────────────────────────────── */

interface MinimalViewTransition {
  ready: Promise<void>;
  finished: Promise<void>;
  skipTransition(): void;
}

let activeTransition: MinimalViewTransition | null = null;
let fadeTimer: ReturnType<typeof setTimeout> | null = null;

function prefersReducedMotion(): boolean {
  try {
    return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  } catch {
    return false;
  }
}

/**
 * Run `apply` (which must synchronously flip the theme on <html> and commit
 * any React state the new snapshot should show) with the best animation the
 * browser and the user's motion preference allow.
 *
 * Rapid toggling: a click while a reveal is still running skips the running
 * one to its end state (its update has already been applied or is applied by
 * `skipTransition`), then starts a fresh reveal from the current state, so the
 * DOM never ends up out of step with the stored preference.
 */
export function runThemeTransition(apply: () => void, origin: Element | null): void {
  const root = document.documentElement;
  const start = (document as Document & {
    startViewTransition?: (cb: () => void) => MinimalViewTransition;
  }).startViewTransition;

  const mode = pickThemeTransitionMode({
    reducedMotion: prefersReducedMotion(),
    supportsViewTransitions: typeof start === "function",
    hidden: document.visibilityState === "hidden",
  });

  if (activeTransition) {
    try { activeTransition.skipTransition(); } catch { /* already done */ }
    activeTransition = null;
  }

  if (mode === "instant") {
    apply();
    return;
  }

  if (mode === "fade") {
    if (fadeTimer) clearTimeout(fadeTimer);
    root.classList.add("nx-theme-fading");
    apply();
    fadeTimer = setTimeout(() => {
      root.classList.remove("nx-theme-fading");
      fadeTimer = null;
    }, FADE_DURATION_MS + 40);
    return;
  }

  const { x, y, radius } = revealGeometry(origin?.getBoundingClientRect() ?? null, {
    width: window.innerWidth,
    height: window.innerHeight,
  });

  // Scopes the pseudo-element CSS in app/globals.css to THIS transition, so
  // any other view transition the app adds later keeps the browser default.
  root.classList.add("nx-theme-vt");
  let vt: MinimalViewTransition;
  try {
    vt = start!.call(document, apply);
  } catch {
    root.classList.remove("nx-theme-vt");
    apply();
    return;
  }
  activeTransition = vt;

  vt.ready
    .then(() => {
      root.animate(
        { clipPath: [`circle(0px at ${x}px ${y}px)`, `circle(${radius}px at ${x}px ${y}px)`] },
        { duration: REVEAL_DURATION_MS, easing: REVEAL_EASING, pseudoElement: "::view-transition-new(root)" },
      );
    })
    .catch(() => { /* skipped or aborted: the update callback still ran */ });

  vt.finished
    .catch(() => {})
    .finally(() => {
      if (activeTransition === vt) {
        activeTransition = null;
        root.classList.remove("nx-theme-vt");
      }
    });
}

