"use client";

import { useEffect, useRef, useState } from "react";
import { flushSync } from "react-dom";
import { Icon } from "./Icon";
import { runThemeTransition } from "./themeTransition";

/**
 * Dark / light switch.
 *
 * Writes `data-theme` on <html> and remembers the choice in localStorage. The
 * FIRST paint is handled by an inline script in app/layout.tsx, not by this
 * component — a React effect runs after hydration, which is one paint too late
 * and shows a white flash on every load for anyone on light.
 *
 * Dark is the default and stays the product's identity; light is opt-in. The
 * rail and top bar are dark in both (see `.nx-dark-island` in globals.css), so
 * this control always sits on a dark surface and does not need to restyle
 * itself when the theme flips.
 *
 * The switch itself is animated by ./themeTransition.ts: a circular reveal
 * from this button (View Transitions API), a short colour cross-fade where
 * that API is missing, and an instant flip under `prefers-reduced-motion`.
 * The icon is a stacked sun + moon that rotate/scale past each other
 * (`.nx-theme-toggle` in app/globals.css).
 */

export const THEME_KEY = "nx-theme";

function paint(light: boolean) {
  const root = document.documentElement;
  if (light) root.setAttribute("data-theme", "light");
  else root.removeAttribute("data-theme");
}

export function ThemeToggle() {
  const [light, setLight] = useState(false);
  /* The theme the customer most recently ASKED for. Read (not captured) by the
     transition's update callback so a rapid double-click whose first reveal
     gets skipped can never land the page on a stale theme. */
  const desired = useRef(false);
  const btn = useRef<HTMLButtonElement>(null);
  /* Bumped per click to re-key the brand-gradient ring pulse. 0 = no pulse
     yet, so nothing animates on first render / hydration. */
  const [pulse, setPulse] = useState(0);

  /* Apply the stored preference on mount, then strip it on unmount.
   *
   * The inline script in app/layout.tsx only runs once, on the very first
   * document load — it never re-fires on a client-side route change, but
   * `<html>` is shared by the whole app (marketing and the dashboard render
   * inside the SAME root layout), so `data-theme` set here otherwise just
   * rides along on any soft navigation. This component only ever mounts
   * inside the dashboard shell, so its mount/unmount IS the "entered/left the
   * portal" signal: apply the saved choice when the customer lands here by
   * a client-side nav (the inline script had nothing to gate for this
   * specific route transition), and remove it the moment they navigate back
   * out, so marketing/login can never inherit a light theme they were never
   * built for — matching the inline script's own now-path-gated behavior.
   */
  useEffect(() => {
    let stored: string | null = null;
    try {
      stored = localStorage.getItem(THEME_KEY);
    } catch {
      /* Private mode or blocked storage — fail closed to dark. */
    }
    const isLight = stored === "light";
    desired.current = isLight;
    setLight(isLight);
    const root = document.documentElement;
    if (isLight) root.setAttribute("data-theme", "light");
    return () => {
      root.removeAttribute("data-theme");
    };
  }, []);

  function toggle() {
    const next = !desired.current;
    desired.current = next;
    try {
      localStorage.setItem(THEME_KEY, next ? "light" : "dark");
    } catch {
      /* Private mode or blocked storage. The theme still applies for this
         session; it just will not be remembered, which is the right failure. */
    }
    setPulse((n) => n + 1);
    runThemeTransition(() => {
      const target = desired.current;
      paint(target);
      // Commit the icon swap synchronously so the View Transition's "new"
      // snapshot already carries it (the morph then plays inside the reveal).
      flushSync(() => setLight(target));
    }, btn.current);
  }

  return (
    <button
      ref={btn}
      type="button"
      onClick={toggle}
      aria-pressed={light}
      aria-label="Light theme"
      title={light ? "Switch to dark theme" : "Switch to light theme"}
      data-light={light ? "" : undefined}
      className="nx-theme-toggle relative grid h-10 w-10 place-items-center rounded-[10px] text-tx-dim transition hover:bg-[rgba(72,148,255,0.08)] hover:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#7b3fef]/70"
    >
      {/* Sun when light is ON (click to go dark), moon when dark is ON (click
          to go light) — the icon names the theme you'd switch TO, matching
          how every other toggle in the shell reads. Both are always rendered
          and cross over each other, so the swap is a morph, not a pop. */}
      <span aria-hidden className="nx-theme-toggle__icon nx-theme-toggle__moon">
        <Icon name="moon" size={18} tone="inherit" />
      </span>
      <span aria-hidden className="nx-theme-toggle__icon nx-theme-toggle__sun">
        <Icon name="sun" size={18} tone="inherit" />
      </span>
      {pulse > 0 && <span key={pulse} aria-hidden className="nx-theme-toggle__ring" />}
    </button>
  );
}
EOF

