/* ══ THEME SWITCH TRANSITION ══════════════════════════════════════════════
   Driven by components/nx/themeTransition.ts (see docs/DOCUMENTATION.md,
   "Theme switch transition").

   1. Circular reveal (View Transitions API). `html.nx-theme-vt` exists only
      for the lifetime of a theme switch, so these rules never touch any
      other view transition. The browser's default root cross-fade is
      switched off; the JS animates `clip-path` on the NEW snapshot from the
      toggle's centre, and the OLD snapshot just sits underneath. The root
      snapshot is a flat image of the whole viewport, so fixed headers,
      canvases (charts, globe) and iframes (noVNC console) are captured as
      they are — nothing inside them is re-laid-out or re-mounted. */
html.nx-theme-vt::view-transition-old(root),
html.nx-theme-vt::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
}
html.nx-theme-vt::view-transition-old(root) { z-index: 1; }
html.nx-theme-vt::view-transition-new(root) { z-index: 2; }

/* 2. Fallback cross-fade where View Transitions don't exist. Colour
      properties only (never transform/size), so nothing can shift, and only
      while the class is on <html> (~280 ms), so normal hover transitions are
      untouched the rest of the time. */
html.nx-theme-fading,
html.nx-theme-fading *,
html.nx-theme-fading *::before,
html.nx-theme-fading *::after {
  transition-property: background-color, border-color, color, fill, stroke, outline-color, box-shadow !important;
  transition-duration: 240ms !important;
  transition-timing-function: ease !important;
  transition-delay: 0s !important;
}

/* 3. The toggle icon: sun and moon stacked, crossing over with a rotate +
      scale. Dark (default) shows the moon in a violet tint; light shows the
      sun in cyan. The button lives on the dark top bar in both themes. */
.nx-theme-toggle__icon {
  grid-area: 1 / 1;
  display: grid;
  place-items: center;
  transition:
    transform 520ms cubic-bezier(0.34, 1.4, 0.64, 1),
    opacity 260ms ease,
    color 200ms ease;
  will-change: transform, opacity;
}
.nx-theme-toggle__moon { color: #a99bff; }
.nx-theme-toggle__sun {
  color: #67e8f9;
  opacity: 0;
  transform: rotate(-90deg) scale(0.4);
}
.nx-theme-toggle[data-light] .nx-theme-toggle__moon {
  opacity: 0;
  transform: rotate(90deg) scale(0.4);
}
.nx-theme-toggle[data-light] .nx-theme-toggle__sun {
  opacity: 1;
  transform: rotate(0deg) scale(1);
}
.nx-theme-toggle:hover .nx-theme-toggle__moon { color: #c4b8ff; }
.nx-theme-toggle:hover .nx-theme-toggle__sun { color: #a5f3fc; }

/* One-shot brand-gradient ring on click (re-keyed per click in React). */
.nx-theme-toggle__ring {
  position: absolute;
  inset: 3px;
  border-radius: 9px;
  pointer-events: none;
  padding: 1.5px;
  background: linear-gradient(135deg, #3b6be8, #7b3fef 60%, var(--color-brand-c));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
  animation: nx-theme-ring 560ms cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
@keyframes nx-theme-ring {
  0%   { opacity: 0.95; transform: scale(0.82); }
  100% { opacity: 0;    transform: scale(1.18); }
}

@media (prefers-reduced-motion: reduce) {
  .nx-theme-toggle__icon { transition: opacity 1ms linear; transform: none !important; }
  .nx-theme-toggle__ring { display: none; }
}
EOF

