 *  the browser behaviour is checked with Playwright (screens in /root/agent-notes/theme-transition). */

test("reduced motion always switches instantly", () => {
  assert.equal(pickThemeTransitionMode({ reducedMotion: true, supportsViewTransitions: true }), "instant");
  assert.equal(pickThemeTransitionMode({ reducedMotion: true, supportsViewTransitions: false }), "instant");
});

test("hidden documents switch instantly (View Transitions abort there)", () => {
  assert.equal(pickThemeTransitionMode({ reducedMotion: false, supportsViewTransitions: true, hidden: true }), "instant");
});

test("View Transitions -> reveal, otherwise cross-fade", () => {
  assert.equal(pickThemeTransitionMode({ reducedMotion: false, supportsViewTransitions: true }), "reveal");
  assert.equal(pickThemeTransitionMode({ reducedMotion: false, supportsViewTransitions: false }), "fade");
});

test("origin is the button centre and the radius reaches the farthest corner", () => {
  const g = revealGeometry({ left: 1180, top: 12, width: 40, height: 40 }, { width: 1280, height: 800 });
  assert.equal(g.x, 1200);
  assert.equal(g.y, 32);
  // farthest corner is bottom-left (0, 800)
  assert.equal(g.radius, Math.ceil(Math.hypot(1200, 768)));
});

test("origin in the middle covers all four corners", () => {
  const vp = { width: 1000, height: 600 };
  const g = revealGeometry({ left: 490, top: 290, width: 20, height: 20 }, vp);
  for (const [cx, cy] of [[0, 0], [vp.width, 0], [0, vp.height], [vp.width, vp.height]]) {
    assert.ok(Math.hypot(cx - g.x, cy - g.y) <= g.radius);
  }
});

test("missing / zero-size / non-finite rect falls back to the top-right corner", () => {
  const vp = { width: 400, height: 900 };
  for (const r of [null, undefined, { left: 10, top: 10, width: 0, height: 0 }, { left: NaN, top: 0, width: 4, height: 4 }]) {
    const g = revealGeometry(r, vp);
    assert.deepEqual([g.x, g.y], [400, 0]);
    assert.equal(g.radius, Math.ceil(Math.hypot(400, 900)));
  }
});

test("off-screen rects are clamped into the viewport", () => {
  const g = revealGeometry({ left: 2000, top: -300, width: 40, height: 40 }, { width: 800, height: 600 });
  assert.deepEqual([g.x, g.y], [800, 0]);
  assert.equal(g.radius, 1000);
});

test("toggle exposes aria-pressed with a stable label, and the CSS is scoped to the switch", () => {
  const root = join(import.meta.dirname, "..");
  const tsx = readFileSync(join(root, "components/nx/ThemeToggle.tsx"), "utf8");
  assert.match(tsx, /aria-pressed=\{light\}/);
  assert.match(tsx, /aria-label="Light theme"/);
  assert.doesNotMatch(tsx, /role="switch"/);
  const css = readFileSync(join(root, "app/globals.css"), "utf8");
  // Never override the browser's default view transition globally.
  assert.doesNotMatch(css, /^::view-transition-(old|new)\(root\)/m);
  assert.match(css, /html\.nx-theme-vt::view-transition-new\(root\)/);
});
