const base = "http://127.0.0.1:3187/theme-shot", out = "/root/agent-notes/theme-transition";
const b = await chromium.launch();
const logs = [];
async function page(opts = {}) {
  const ctx = await b.newContext({ viewport: opts.vp ?? { width: 1440, height: 900 }, reducedMotion: opts.reduced ? "reduce" : "no-preference" });
  if (opts.noVT) await ctx.addInitScript(() => { delete Document.prototype.startViewTransition; });
  const p = await ctx.newPage();
  p.on("console", (m) => { if (["error", "warning"].includes(m.type())) logs.push(`[${opts.tag}] ${m.type()}: ${m.text().slice(0, 200)}`); });
  p.on("pageerror", (e) => logs.push(`[${opts.tag}] pageerror: ${e.message}`));
  await p.goto(base, { waitUntil: "networkidle" });
  await p.waitForTimeout(800);
  return { ctx, p };
}
const toggle = (p) => p.locator("button.nx-theme-toggle");
const state = (p) => p.evaluate(() => ({ theme: document.documentElement.getAttribute("data-theme"), vt: document.documentElement.classList.contains("nx-theme-vt"), fading: document.documentElement.classList.contains("nx-theme-fading"), pressed: document.querySelector("button.nx-theme-toggle")?.getAttribute("aria-pressed"), stored: localStorage.getItem("nx-theme") }));

async function revealSeq(p, dir, tag) {
  await toggle(p).click();
  await p.waitForFunction(() => document.getAnimations().some((a) => a.effect?.pseudoElement === "::view-transition-new(root)"));
  await p.evaluate(() => { for (const a of document.getAnimations()) if (a.effect?.pseudoElement) a.pause(); });
  for (const t of [0, 100, 200, 300, 400, 520]) {
    await p.evaluate((t) => { for (const a of document.getAnimations()) if (a.effect?.pseudoElement === "::view-transition-new(root)") a.currentTime = t; }, t);
    await p.waitForTimeout(60);
    await p.screenshot({ path: `${out}/${tag}-${dir}-${String(t).padStart(3, "0")}ms.png` });
  }
  await p.evaluate(() => { for (const a of document.getAnimations()) if (a.effect?.pseudoElement) a.play(); });
  await p.waitForTimeout(700);
  await p.screenshot({ path: `${out}/${tag}-${dir}-done.png` });
  console.log(tag, dir, "after:", JSON.stringify(await state(p)));
}

// 1. Reveal, both directions, desktop + phone
for (const [vp, tag] of [[{ width: 1440, height: 900 }, "reveal-1440"], [{ width: 390, height: 844 }, "reveal-390"]]) {
  const { ctx, p } = await page({ vp, tag });
  console.log(tag, "initial:", JSON.stringify(await state(p)));
  await revealSeq(p, "dark-to-light", tag);
  await revealSeq(p, "light-to-dark", tag);
  await ctx.close();
}

// 2. Rapid toggling (5 clicks in ~150ms) -> consistent end state, no stuck class
{
  const { ctx, p } = await page({ tag: "rapid" });
  for (let i = 0; i < 5; i++) { await toggle(p).click(); await p.waitForTimeout(30); }
  await p.waitForTimeout(1000);
  console.log("rapid x5:", JSON.stringify(await state(p)), "(expect light, vt false)");
  for (let i = 0; i < 4; i++) await toggle(p).click({ delay: 0 });
  await p.waitForTimeout(1000);
  console.log("rapid x4 more:", JSON.stringify(await state(p)), "(expect dark => theme null)");
  await ctx.close();
}

// 3. Reduced motion -> instant
{
  const { ctx, p } = await page({ reduced: true, tag: "reduced" });
  await toggle(p).click();
  const s = await p.evaluate(() => ({ theme: document.documentElement.getAttribute("data-theme"), anims: document.getAnimations().filter((a) => a.effect?.pseudoElement).length, vt: document.documentElement.classList.contains("nx-theme-vt") }));
  console.log("reduced, same tick after click:", JSON.stringify(s), "(expect light, 0 anims, vt false)");
  await p.screenshot({ path: `${out}/reduced-motion-after-click.png` });
