}

// 4. No View Transitions -> cross-fade fallback, both directions
{
  const { ctx, p } = await page({ noVT: true, tag: "fallback" });
  console.log("fallback supportsVT:", await p.evaluate(() => typeof document.startViewTransition));
  for (const dir of ["dark-to-light", "light-to-dark"]) {
    await toggle(p).click();
    for (const t of [40, 100, 160, 240]) {
      await p.waitForTimeout(t === 40 ? 40 : 60);
      await p.screenshot({ path: `${out}/fallback-fade-${dir}-${String(t).padStart(3, "0")}ms.png` });
    }
    await p.waitForTimeout(400);
    console.log("fallback", dir, JSON.stringify(await state(p)));
  }
  await ctx.close();
}

// 5. Keyboard: Tab to the toggle, Space and Enter
{
  const { ctx, p } = await page({ tag: "kbd" });
  await toggle(p).focus();
