  await p.keyboard.press("Space"); await p.waitForTimeout(800);
  console.log("kbd after Space:", JSON.stringify(await state(p)));
  await p.keyboard.press("Enter"); await p.waitForTimeout(800);
  console.log("kbd after Enter:", JSON.stringify(await state(p)), "| focus kept:", await toggle(p).evaluate((e) => e === document.activeElement));
  await p.keyboard.press("Space"); await p.waitForTimeout(800);
