 app/globals.css               | 87 +++++++++++++++++++++++++++++++++++++++++++
 components/nx/ThemeToggle.tsx | 62 +++++++++++++++++++++++-------
 docs/DOCUMENTATION.md         | 13 +++++++
 3 files changed, 149 insertions(+), 13 deletions(-)
 * pointer event to the transition root, so a second MOUSE click is absorbed
 * (by design of the View Transitions API). Keyboard repeats on the focused
 * toggle still arrive: a toggle while a reveal is still running skips the running
 * one to its end state (its update has already been applied or is applied by
 * `skipTransition`), then starts a fresh reveal from the current state, so the
 * DOM never ends up out of step with the stored preference. `apply` should be
 * idempotent and read the DESIRED theme at call time (not capture it), so a
 * skipped transition's late callback can't re-apply a stale theme.
 */
export function runThemeTransition(apply: () => void, origin: Element | null): void {
  const root = document.documentElement;
  const start = (document as Document & {
    startViewTransition?: (cb: () => void) => MinimalViewTransition;
  }).startViewTransition;

  const mode = pickThemeTransitionMode({
    reducedMotion: prefersReducedMotion(),
    supportsViewTransitions: typeof start === "function",
    hidden: document.visibilityState === "hidden",
  });

  if (activeTransition) {
    try { activeTransition.skipTransition(); } catch { /* already done */ }
    activeTransition = null;
  }

  if (mode === "instant") {
    apply();
    return;
  }

  if (mode === "fade") {
    if (fadeTimer) clearTimeout(fadeTimer);
    root.classList.add("nx-theme-fading");
    apply();
    fadeTimer = setTimeout(() => {
      root.classList.remove("nx-theme-fading");
      fadeTimer = null;
    }, FADE_DURATION_MS + 40);
    return;
  }

  const { x, y, radius } = revealGeometry(origin?.getBoundingClientRect() ?? null, {
    width: window.innerWidth,
    height: window.innerHeight,
  });

